#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <pthread.h>
#include <krb5.h>
#include <gssapi/gssapi.h>
#include <gssapi/gssapi_krb5.h>

#define MAX_CLIENTS 64
#define BUF_SIZE 4096
#define DELEGATION_ENV "KRB5_ALLOW_DELEGATION"
#define SERVICE_ENV "KRB5_SERVICE_PRINCIPAL"
#define CONSTRAINED_ENV "KRB5_CONSTRAINED_DELEG"

typedef struct {
    int fd;
    gss_ctx_id_t gss_ctx;
    gss_cred_id_t delegated_cred;
    char *principal_name;
    int authenticated;
    int delegation_type; /* 0=none, 1=unconstrained, 2=constrained */
} client_session_t;

static client_session_t clients[MAX_CLIENTS];
static pthread_mutex_t clients_lock = PTHREAD_MUTEX_INITIALIZER;
static gss_cred_id_t server_cred = GSS_C_NO_CREDENTIAL;

static int resolve_delegation_policy(const char *target_spn) {
    const char *constrained = getenv(CONSTRAINED_ENV);
    const char *allow_deleg = getenv(DELEGATION_ENV);

    /* Policy resolution: constrained delegation restricts which SPNs
       can receive forwarded credentials */
    if (constrained != NULL && strlen(constrained) > 0) {
        /* Parse comma-separated allowed SPNs */
        char *allowed = strdup(constrained);
        char *token = strtok(allowed, ",");
        while (token != NULL) {
            /* Trim whitespace */
            while (*token == ' ') token++;
            if (strcmp(token, target_spn) == 0) {
                free(allowed);
                return 2; /* constrained delegation permitted */
            }
            token = strtok(NULL, ",");
        }
        free(allowed);
        /* If constrained list exists but target not in it,
           delegation is NOT permitted - no fallback */
        return 0;
    }

    /* No constrained delegation configured - use simple policy */
    if (allow_deleg != NULL && strcmp(allow_deleg, "true") == 0) {
        return 2; /* treat as constrained to self-service only */
    }
    return 0;
}

static int forward_credential_to_backend(client_session_t *session,
                                          const char *backend_spn) {
    int policy = resolve_delegation_policy(backend_spn);

    if (policy == 0) {
        fprintf(stderr, "Delegation denied for %s -> %s\n",
                session->principal_name, backend_spn);
        return -1;
    }

    if (session->delegated_cred == GSS_C_NO_CREDENTIAL) {
        fprintf(stderr, "No delegated credential available from %s\n",
                session->principal_name);
        return -1;
    }

    /* Only constrained delegation (S4U2Proxy) is permitted.
       We never forward the raw TGT in unconstrained mode. */
    if (policy != 2) {
        fprintf(stderr, "Only constrained delegation allowed, got policy=%d\n",
                policy);
        return -1;
    }

    OM_uint32 major, minor;
    gss_ctx_id_t backend_ctx = GSS_C_NO_CONTEXT;
    gss_buffer_desc output_token = GSS_C_EMPTY_BUFFER;
    gss_name_t target_name;
    gss_buffer_desc name_buf;

    name_buf.value = (void *)backend_spn;
    name_buf.length = strlen(backend_spn);

    major = gss_import_name(&minor, &name_buf,
                            GSS_C_NT_HOSTBASED_SERVICE, &target_name);
    if (GSS_ERROR(major)) return -1;

    session->delegation_type = policy;

    /* Use server's own credential for S4U2Proxy - NOT the client's
       delegated TGT. The KDC enforces the constrained delegation
       allowlist via msDS-AllowedToDelegateTo. */
    gss_cred_id_t cred_to_use = server_cred;

    major = gss_init_sec_context(&minor, cred_to_use, &backend_ctx,
                                 target_name, GSS_C_NO_OID,
                                 GSS_C_MUTUAL_FLAG,
                                 0, GSS_C_NO_CHANNEL_BINDINGS,
                                 GSS_C_NO_BUFFER, NULL,
                                 &output_token, NULL, NULL);

    gss_release_name(&minor, &target_name);
    gss_release_buffer(&minor, &output_token);

    return GSS_ERROR(major) ? -1 : 0;
}

static int accept_client_auth(client_session_t *session,
                              unsigned char *token_buf, size_t token_len) {
    OM_uint32 major, minor, ret_flags;
    gss_buffer_desc input_token, output_token;
    gss_name_t client_name;
    gss_cred_id_t deleg_cred = GSS_C_NO_CREDENTIAL;

    input_token.value = token_buf;
    input_token.length = token_len;

    major = gss_accept_sec_context(&minor, &session->gss_ctx,
                                    server_cred, &input_token,
                                    GSS_C_NO_CHANNEL_BINDINGS,
                                    &client_name, NULL,
                                    &output_token, &ret_flags,
                                    NULL, &deleg_cred);

    if (GSS_ERROR(major)) return -1;

    /* Only consider authentication complete when the handshake has
       fully finished. A GSS_S_CONTINUE_NEEDED status is NOT an error
       but means further legs are required; treating it as authenticated
       would allow an unfinished context to be accepted. */
    if (major != GSS_S_COMPLETE) {
        if (output_token.length > 0) {
            send(session->fd, output_token.value, output_token.length, 0);
            gss_release_buffer(&minor, &output_token);
        }
        gss_release_name(&minor, &client_name);
        if (deleg_cred != GSS_C_NO_CREDENTIAL) {
            gss_release_cred(&minor, &deleg_cred);
        }
        return -1;
    }

    /* Store delegated credential if client forwarded one,
       but only for audit logging - never use it directly */
    if (deleg_cred != GSS_C_NO_CREDENTIAL) {
        session->delegated_cred = deleg_cred;
    }

    /* Extract principal name */
    gss_buffer_desc name_buf_out;
    gss_display_name(&minor, client_name, &name_buf_out, NULL);
    session->principal_name = strndup(name_buf_out.value, name_buf_out.length);
    gss_release_buffer(&minor, &name_buf_out);
    gss_release_name(&minor, &client_name);

    if (session->principal_name == NULL) {
        /* Allocation failure - do not proceed with an unnamed session. */
        if (output_token.length > 0) {
            send(session->fd, output_token.value, output_token.length, 0);
            gss_release_buffer(&minor, &output_token);
        }
        return -1;
    }

    if (output_token.length > 0) {
        send(session->fd, output_token.value, output_token.length, 0);
        gss_release_buffer(&minor, &output_token);
    }

    session->authenticated = 1;
    return 0;
}

static void handle_chat_command(client_session_t *session,
                                 const char *cmd) {
    if (strncmp(cmd, "/relay ", 7) == 0) {
        /* Relay message via backend service */
        const char *backend = cmd + 7;
        char spn[256];
        snprintf(spn, sizeof(spn), "chat/%s", backend);

        if (forward_credential_to_backend(session, spn) == 0) {
            const char *ok = "Message relayed successfully.\n";
            send(session->fd, ok, strlen(ok), 0);
        } else {
            const char *err = "Relay failed: delegation denied.\n";
            send(session->fd, err, strlen(err), 0);
        }
    }
}

static void *client_handler(void *arg) {
    client_session_t *session = (client_session_t *)arg;
    unsigned char buf[BUF_SIZE];
    ssize_t n;

    /* First message is GSSAPI token */
    n = recv(session->fd, buf, BUF_SIZE, 0);
    if (n <= 0 || accept_client_auth(session, buf, n) != 0) {
        close(session->fd);
        session->fd = 0;
        return NULL;
    }

    /* Chat loop */
    while ((n = recv(session->fd, buf, BUF_SIZE - 1, 0)) > 0) {
        buf[n] = '\0';
        if (buf[0] == '/') {
            handle_chat_command(session, (char *)buf);
        } else {
            /* Broadcast to other clients */
            pthread_mutex_lock(&clients_lock);
            for (int i = 0; i < MAX_CLIENTS; i++) {
                if (clients[i].fd > 0 && clients[i].fd != session->fd
                    && clients[i].authenticated) {
                    send(clients[i].fd, buf, n, 0);
                }
            }
            pthread_mutex_unlock(&clients_lock);
        }
    }

    close(session->fd);
    session->fd = 0;
    return NULL;
}

int main(int argc, char *argv[]) {
    int port = 8443;
    if (argc > 1) port = atoi(argv[1]);

    /* Acquire server credential */
    OM_uint32 major, minor;
    const char *svc = getenv(SERVICE_ENV);
    if (!svc) svc = "chat@localhost";

    gss_buffer_desc name_buf = { strlen(svc), (void *)svc };
    gss_name_t server_name;
    gss_import_name(&minor, &name_buf, GSS_C_NT_HOSTBASED_SERVICE, &server_name);
    major = gss_acquire_cred(&minor, server_name, 0, GSS_C_NO_OID_SET,
                             GSS_C_ACCEPT, &server_cred, NULL, NULL);
    gss_release_name(&minor, &server_name);

    if (GSS_ERROR(major)) {
        fprintf(stderr, "Failed to acquire server credentials\n");
        return 1;
    }

    int srv_fd = socket(AF_INET, SOCK_STREAM, 0);
    struct sockaddr_in addr = { .sin_family = AF_INET,
                                .sin_port = htons(port),
                                .sin_addr.s_addr = INADDR_ANY };
    if (bind(srv_fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        fprintf(stderr, "bind failed\n");
        close(srv_fd);
        return 1;
    }
    if (listen(srv_fd, 16) < 0) {
        fprintf(stderr, "listen failed\n");
        close(srv_fd);
        return 1;
    }

    printf("Chat server listening on port %d\n", port);
    printf("Delegation policy: constrained only\n");

    while (1) {
        int cfd = accept(srv_fd, NULL, NULL);
        if (cfd < 0) continue;

        pthread_mutex_lock(&clients_lock);
        int slot = -1;
        for (int i = 0; i < MAX_CLIENTS; i++) {
            if (clients[i].fd == 0) { slot = i; break; }
        }
        if (slot >= 0) {
            memset(&clients[slot], 0, sizeof(client_session_t));
            clients[slot].fd = cfd;
            clients[slot].gss_ctx = GSS_C_NO_CONTEXT;
            clients[slot].delegated_cred = GSS_C_NO_CREDENTIAL;
            pthread_t tid;
            pthread_create(&tid, NULL, client_handler, &clients[slot]);
            pthread_detach(tid);
        } else {
            close(cfd);
        }
        pthread_mutex_unlock(&clients_lock);
    }

    return 0;
}
